const o=r=>{try{const e=new(window.AudioContext||window.webkitAudioContext),c=e.createOscillator(),n=e.createGain();c.connect(n),n.connect(e.destination);let a=400,t=.1;switch(r){case"click":a=800,t=.05;break;case"success":a=784,t=.2;break;case"error":a=200,t=.15;break;case"notification":a=600,t=.12;break;case"reward":a=900,t=.25;break;case"level-up":a=1047,t=.3;break}c.frequency.value=a,n.gain.setValueAtTime(.3,e.currentTime),n.gain.exponentialRampToValueAtTime(.01,e.currentTime+t),c.start(e.currentTime),c.stop(e.currentTime+t)}catch{}};export{o as p};
